export class Lightbox{constructor(){this.box=document.querySelector("#lightbox"),this.box&&"function"==typeof this.box.showModal&&(this.img=this.box.querySelector("[data-lightbox-img]"),this.init())}init(){document.querySelectorAll("[data-lightbox]").forEach(t=>t.addEventListener("click",()=>{const i=t.querySelector("img");this.img.src=t.dataset.lightbox,this.img.alt=i?i.alt:"",this.box.showModal()})),this.box.querySelector("[data-lightbox-close]").addEventListener("click",()=>this.box.close()),this.box.addEventListener("click",t=>{t.target!==this.box&&t.target!==this.img||this.box.close()})}}